            const cfg   = $('Ajustes y cupo').first().json.cfg;
            const lead  = $('Uno por uno').first().json;
            const datos = JSON.parse(textoDelModelo($input.first().json));

            let mensaje = limpiar(datos.mensaje, 420);

            // Últimas rejas, por si el modelo se salta el prompt.
            mensaje = mensaje.replace(/https?:\/\/\S+/g, '').replace(/ {2,}/g, ' ').trim();

            const baja = 'Si no te interesa dime "baja" y no te escribo más.';
            if (!/\bbaja\b/i.test(mensaje)) {
              mensaje += String.fromCharCode(10, 10) + baja;
            }

            if (mensaje.length < 25) {
              throw new Error('Mensaje demasiado corto, no se envía: ' + mensaje);
            }

            return [{ json: {
              mensaje,
              mensaje_sql: lit(mensaje),
              gancho_sql:  lit(datos.gancho || ''),
              lead_id:     lead.id,
              telefono:    lead.telefono,
              delay_ms:    Math.min(60, Math.max(20, mensaje.length / 3)) * 100,
            } }];

